        self._current_stage = 0
        self.progress_bar.setValue(0)
        self.stage_label.setText("Preparing...")
        self.detail_label.setText("")
        for dot in self.dot_labels:
            dot.setStyleSheet(f"color: {t.HDA_STAGE_INACTIVE}; font-size: 8px;")
